jsonl:
{"op":"add","path":"/root","value":"main"}
{"op":"add","path":"/state/people","value":20}
{"op":"add","path":"/state/perPerson","value":50}
{"op":"add","path":"/state/fixed","value":100}
{"op":"add","path":"/state/budget","value":2000}
{"op":"add","path":"/elements/main","value":{"type":"Col","props":{"gap":4},"children":["h","takeaway","facts","input-card","table-card","chart-card","alerts","analyze-row"]}}
{"op":"add","path":"/elements/h","value":{"type":"Header","props":{"text":"预算试算","size":"xl"}}}
{"op":"add","path":"/elements/takeaway","value":{"type":"Text","props":{"value":{"$calc":"'当前配置总费用 ' + number(${/people} * ${/perPerson} + ${/fixed}, 0) + '，余额 ' + number(${/budget} - (${/people} * ${/perPerson} + ${/fixed}), 0) + '。'"},"size":"md","color":"secondary"}}}
{"op":"add","path":"/elements/facts","value":{"type":"Row","props":{"gap":6,"justify":"start"},"children":["fact-total","fact-budget","fact-balance"]}}
{"op":"add","path":"/elements/fact-total","value":{"type":"Fact","props":{"label":"总费用","value":{"$calc":"number(${/people} * ${/perPerson} + ${/fixed}, 0)"}}}}
{"op":"add","path":"/elements/fact-budget","value":{"type":"Fact","props":{"label":"预算","value":{"$calc":"number(${/budget}, 0)"}}}}
{"op":"add","path":"/elements/fact-balance","value":{"type":"Fact","props":{"label":"余额","value":{"$calc":"number(${/budget} - (${/people} * ${/perPerson} + ${/fixed}), 0)"}}}}
{"op":"add","path":"/elements/input-card","value":{"type":"Card","props":{"title":"输入参数","padding":4},"children":["people-slider","num-row"]}}
{"op":"add","path":"/elements/people-slider","value":{"type":"Slider","props":{"label":"人数","min":1,"max":200,"step":1,"unit":"人","defaultValue":{"$bindState":"/people"}}}}
{"op":"add","path":"/elements/num-row","value":{"type":"Row","props":{"gap":6,"justify":"start","align":"end"},"children":["ni-per","ni-fixed","ni-budget"]}}
{"op":"add","path":"/elements/ni-per","value":{"type":"NumberInput","props":{"label":"每人费用","value":{"$bindState":"/perPerson"},"min":0,"step":1}}}
{"op":"add","path":"/elements/ni-fixed","value":{"type":"NumberInput","props":{"label":"固定费用","value":{"$bindState":"/fixed"},"min":0,"step":1}}}
{"op":"add","path":"/elements/ni-budget","value":{"type":"NumberInput","props":{"label":"预算","value":{"$bindState":"/budget"},"min":0,"step":1}}}
{"op":"add","path":"/elements/table-card","value":{"type":"Card","props":{"title":"费用拆分","padding":4},"children":["cost-table"]}}
{"op":"add","path":"/elements/cost-table","value":{"type":"Table","props":{"columns":[{"label":"项目"},{"label":"计算方式"},{"label":"金额","align":"end","format":{"kind":"number","decimals":0}}],"rows":[["人员费用",{"$template":"${/people} 人 × ${/perPerson}"},{"$calc":"${/people} * ${/perPerson}"}],["固定费用","固定支出",{"$state":"/fixed"}],["总费用","人员费用 + 固定费用",{"$calc":"${/people} * ${/perPerson} + ${/fixed}"}],["预算","可用额度",{"$state":"/budget"}],["余额","预算 − 总费用",{"$calc":"${/budget} - (${/people} * ${/perPerson} + ${/fixed})"}]]}}}
{"op":"add","path":"/elements/chart-card","value":{"type":"Card","props":{"title":"总费用与预算对比","padding":4},"children":["cost-chart"]}}
{"op":"add","path":"/elements/cost-chart","value":{"type":"Chart","props":{"variant":"bar","color":"emphasis","showAxis":true,"data":[{"label":"总费用","value":{"$calc":"${/people} * ${/perPerson} + ${/fixed}"}},{"label":"预算","value":{"$state":"/budget"}}]}}}
{"op":"add","path":"/elements/alerts","value":{"type":"Col","props":{"gap":2},"children":["alert-over","alert-ok"]}}
{"op":"add","path":"/elements/alert-over","value":{"type":"Alert","props":{"tone":"danger","title":"已超出预算","description":{"$calc":"'超出 ' + number((${/people} * ${/perPerson} + ${/fixed}) - ${/budget}, 0) + '，可下调人数、每人费用或固定费用。'"},"visible":{"$calc":"${/budget} - (${/people} * ${/perPerson} + ${/fixed}) < 0"}}}}
{"op":"add","path":"/elements/alert-ok","value":{"type":"Alert","props":{"tone":"success","title":"预算尚有余额","description":{"$calc":"'还剩 ' + number(${/budget} - (${/people} * ${/perPerson} + ${/fixed}), 0) + ' 可用额度。'"},"visible":{"$calc":"${/budget} - (${/people} * ${/perPerson} + ${/fixed}) >= 0"}}}}
{"op":"add","path":"/elements/analyze-row","value":{"type":"Row","props":{"gap":4,"justify":"between","align":"center"},"children":["cap-send","btn-analyze"]}}
{"op":"add","path":"/elements/cap-send","value":{"type":"Caption","props":{"value":"仅在点击按钮后，才会把当前人数与三项金额发送给助手分析。"}}}
{"op":"add","path":"/elements/btn-analyze","value":{"type":"Button","props":{"label":"分析当前预算","buttonStyle":"primary"},"on":{"press":{"action":"analyze","params":{"prompt":"分析当前预算试算结果，判断是否超支并给出调整建议","paths":["/people","/perPerson","/fixed","/budget"]}}}}}
